type JogWheelProps = { onScrub: (deltaTurns: number) => void; onTouch?: (touched: boolean) => void };

export const JogWheel_MIN = {"base":[6,6]};

export function JogWheel(props: JogWheelProps) {
  const uid = useRef("jogwheel-" + Math.random().toString(36).slice(2)).current;
  const [angle, setAngle] = useState(0);
  const [touched, setTouched] = useState(false);
  const [vel, setVel] = useState(0);
  const dragRef = useRef<{ last: number; el: HTMLElement | null } | null>(null);
  const velRef = useRef(0);

  useEffect(() => {
    if (touched) return;
    let raf = 0;
    let running = true;
    const tick = () => {
      if (!running) return;
      velRef.current *= 0.94;
      if (Math.abs(velRef.current) < 0.0002) {
        velRef.current = 0;
        setVel(0);
        return;
      }
      setVel(velRef.current);
      setAngle((a) => a + velRef.current * 360);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => { running = false; cancelAnimationFrame(raf); };
  }, [touched]);

  const angleAt = (e: any, el: HTMLElement) => {
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    return (Math.atan2(e.clientY - cy, e.clientX - cx) * 180) / Math.PI;
  };

  const down = (e: any) => {
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);
    dragRef.current = { last: angleAt(e, el), el };
    velRef.current = 0;
    setVel(0);
    setTouched(true);
    if (props.onTouch) props.onTouch(true);
  };

  const move = (e: any) => {
    const d = dragRef.current;
    if (!d) return;
    const el = e.currentTarget as HTMLElement;
    const a = angleAt(e, el);
    let diff = a - d.last;
    if (diff > 180) diff -= 360;
    if (diff < -180) diff += 360;
    d.last = a;
    const turns = diff / 360;
    velRef.current = turns;
    setVel(turns);
    setAngle((prev) => prev + diff);
    props.onScrub(turns);
  };

  const up = (e: any) => {
    if (!dragRef.current) return;
    dragRef.current = null;
    setTouched(false);
    if (props.onTouch) props.onTouch(false);
    try { (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId); } catch (err) {}
  };

  const spin = Math.min(1, Math.abs(vel) * 12);
  const grooves: number[] = [];
  for (let i = 0; i < 9; i++) grooves.push(30 + i * 4.2);
  const marks: number[] = [];
  for (let i = 0; i < 36; i++) marks.push(i * 10);

  const floor = JogWheel_MIN.base;

  return (
    <div
      className="h-full w-full relative touch-none select-none"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
      onPointerDown={down}
      onPointerMove={move}
      onPointerUp={up}
      onPointerCancel={up}
    >
      <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full">
        <defs>
          <radialGradient id={uid + "-platter"} cx="38%" cy="32%" r="78%">
            <stop offset="0%" stopColor="#3f3f46" />
            <stop offset="55%" stopColor="#18181b" />
            <stop offset="100%" stopColor="#09090b" />
          </radialGradient>
          <radialGradient id={uid + "-label"} cx="40%" cy="34%" r="70%">
            <stop offset="0%" stopColor="#f59e0b" />
            <stop offset="70%" stopColor="#c2410c" />
            <stop offset="100%" stopColor="#7c2d12" />
          </radialGradient>
          <linearGradient id={uid + "-rim"} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#52525b" />
            <stop offset="100%" stopColor="#18181b" />
          </linearGradient>
          <radialGradient id={uid + "-glow"} cx="50%" cy="50%" r="50%">
            <stop offset="60%" stopColor="rgba(251,191,36,0)" />
            <stop offset="100%" stopColor="rgba(251,191,36,0.45)" />
          </radialGradient>
        </defs>

        <circle cx="50" cy="50" r="49" fill={"url(#" + uid + "-rim)"} stroke="rgba(251,191,36,0.2)" strokeWidth="0.8" />
        <circle
          cx="50"
          cy="50"
          r="49"
          fill={"url(#" + uid + "-glow)"}
          style={{ opacity: touched ? 0.9 : 0.15 + spin * 0.5, transition: "opacity 200ms ease-out" }}
        />

        <g style={{ transform: "rotate(" + angle + "deg)", transformOrigin: "50px 50px" }}>
          {marks.map((m, i) => (
            <rect
              key={"m-" + i}
              x="49.6"
              y="2.6"
              width="0.8"
              height={i % 9 === 0 ? 5.5 : 3}
              rx="0.4"
              fill={i % 9 === 0 ? "rgba(251,191,36,0.75)" : "rgba(161,161,170,0.35)"}
              style={{ transform: "rotate(" + m + "deg)", transformOrigin: "50px 50px" }}
            />
          ))}
          <circle cx="50" cy="50" r="43" fill={"url(#" + uid + "-platter")} stroke="rgba(0,0,0,0.8)" strokeWidth="1" />
          {grooves.map((g, i) => (
            <circle key={"g-" + i} cx="50" cy="50" r={g} fill="none" stroke="rgba(113,113,122,0.18)" strokeWidth="0.35" />
          ))}
          <circle cx="50" cy="50" r="26" fill={"url(#" + uid + "-label)"} stroke="rgba(0,0,0,0.6)" strokeWidth="0.8" />
          <circle cx="50" cy="50" r="26" fill="none" stroke="rgba(254,243,199,0.25)" strokeWidth="0.4" />
          <rect x="49.3" y="24" width="1.4" height="10" rx="0.7" fill="rgba(9,9,11,0.85)" />
          <circle cx="50" cy="50" r="3.2" fill="#09090b" stroke="rgba(251,191,36,0.4)" strokeWidth="0.5" />
        </g>

        <circle
          cx="50"
          cy="50"
          r="46"
          fill="none"
          stroke={touched ? "rgba(251,191,36,0.85)" : "rgba(251,146,60,0.25)"}
          strokeWidth={touched ? 1.4 : 0.7}
          strokeDasharray="3 6"
          style={{
            transform: "rotate(" + angle * 0.5 + "deg)",
            transformOrigin: "50px 50px",
            transition: "stroke 150ms ease-out, stroke-width 150ms ease-out",
          }}
        />
        <circle
          cx="50"
          cy="50"
          r="31"
          fill="none"
          stroke="rgba(45,212,191,0.5)"
          strokeWidth="0.8"
          strokeDasharray={String(Math.min(195, spin * 195)) + " 400"}
          strokeLinecap="round"
          transform="rotate(-90 50 50)"
          style={{ opacity: spin > 0.02 ? 1 : 0, transition: "opacity 200ms ease-out" }}
        />
      </svg>
    </div>
  );
}

type SlipIndicatorProps = { slip: number };

export const SlipIndicator_MIN = {"base":[3.5,1.25]};

export function SlipIndicator(props: SlipIndicatorProps) {
  const uid = useRef("slipindicator-" + Math.random().toString(36).slice(2)).current;
  const raw = typeof props.slip === "number" && isFinite(props.slip) ? props.slip : 0;
  const s = Math.max(-1, Math.min(1, raw));
  const coordinated = Math.abs(s) < 0.12;

  const W = 120;
  const H = 38;
  const travel = 34;
  const cx = 60 + s * travel;
  const r = 9.5;

  return (
    <div
      className="h-full w-full"
      style={{ minWidth: SlipIndicator_MIN.base[0] + "rem", minHeight: SlipIndicator_MIN.base[1] + "rem" }}
    >
      <svg viewBox={"0 0 " + W + " " + H} preserveAspectRatio="xMidYMid meet" className="h-full w-full block">
        <defs>
          <linearGradient id={uid + "-well"} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#020617" />
            <stop offset="55%" stopColor="#0b1220" />
            <stop offset="100%" stopColor="#020617" />
          </linearGradient>
          <radialGradient id={uid + "-ball"} cx="35%" cy="28%" r="80%">
            <stop offset="0%" stopColor={coordinated ? "#ecfeff" : "#fefce8"} />
            <stop offset="45%" stopColor={coordinated ? "#67e8f9" : "#fcd34d"} />
            <stop offset="100%" stopColor={coordinated ? "#0e7490" : "#b45309"} />
          </radialGradient>
          <filter id={uid + "-glow"} x="-80%" y="-80%" width="260%" height="260%">
            <feGaussianBlur stdDeviation="2.4" result="b" />
            <feMerge>
              <feMergeNode in="b" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <clipPath id={uid + "-clip"}>
            <path d="M14 6 L106 6 L112 30 L8 30 Z" />
          </clipPath>
        </defs>

        {/* trapezoid well */}
        <path
          d="M14 6 L106 6 L112 30 L8 30 Z"
          fill={"url(#" + uid + "-well)"}
          stroke="rgba(6,182,212,0.18)"
          strokeWidth="1.2"
        />

        <g clipPath={"url(#" + uid + "-clip")}>
          {/* inner sheen */}
          <path d="M14 6 L106 6 L109 16 L11 16 Z" fill="rgba(148,163,184,0.10)" />

          {/* ball */}
          <g
            className="transition-transform duration-300 ease-in-out"
            style={{ transform: "translateX(" + (cx - 60) + "px)" }}
          >
            <ellipse cx="60" cy="21.5" rx={r + 1.5} ry={r * 0.55} fill="rgba(0,0,0,0.55)" />
            <circle
              cx="60"
              cy="19"
              r={r}
              fill={"url(#" + uid + "-ball)"}
              filter={coordinated ? undefined : "url(#" + uid + "-glow)"}
            />
            <circle cx="60" cy="19" r={r} fill="none" stroke="rgba(2,6,23,0.6)" strokeWidth="0.8" />
            <ellipse cx="56.6" cy="15.6" rx="3.1" ry="2.1" fill="rgba(255,255,255,0.55)" />
          </g>
        </g>

        {/* cage lines */}
        <g stroke={coordinated ? "#a3e635" : "rgba(165,243,252,0.45)"} strokeWidth="1.4" strokeLinecap="round" className="transition-all duration-200 ease-out">
          <line x1="49" y1="5" x2="48" y2="31" />
          <line x1="71" y1="5" x2="72" y2="31" />
        </g>

        {/* edge ticks */}
        <g stroke="rgba(165,243,252,0.35)" strokeWidth="1" strokeLinecap="round">
          <line x1="22" y1="8" x2="21" y2="14" />
          <line x1="98" y1="8" x2="99" y2="14" />
        </g>

        {coordinated ? (
          <path
            d="M14 6 L106 6 L112 30 L8 30 Z"
