type JogWheelProps = { angle: number; spinning: boolean; onScrub: (deltaRevolutions: number) => void; mode?: 'vinyl' | 'jog' };

export const JogWheel_MIN = {"base":[6,6]};

export function JogWheel(props: JogWheelProps) {
  const { angle, spinning, onScrub } = props;
  const mode = props.mode || "vinyl";
  const uid = useRef("jogwheel-" + Math.random().toString(36).slice(2)).current;
  const [drag, setDrag] = useState(false);
  const [hover, setHover] = useState(false);
  const last = useRef(0);
  const svgRef = useRef<any>(null);

  const angAt = (e: any) => {
    const el = svgRef.current;
    if (!el) return 0;
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    return Math.atan2(e.clientY - cy, e.clientX - cx) * 180 / Math.PI;
  };

  const down = (e: any) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    last.current = angAt(e);
    setDrag(true);
  };
  const move = (e: any) => {
    if (!drag) return;
    const a = angAt(e);
    let d = a - last.current;
    if (d > 180) d -= 360;
    if (d < -180) d += 360;
    last.current = a;
    onScrub(d / 360);
  };
  const up = (e: any) => {
    if (!drag) return;
    try { e.currentTarget.releasePointerCapture(e.pointerId); } catch (err) {}
    setDrag(false);
  };

  const rot = "rotate(" + angle + " 100 100)";
  const isV = mode === "vinyl";
  const accent = isV ? "#22d3ee" : "#fbbf24";

  const grooves = [];
  for (let i = 0; i < 16; i++) {
    const r = 92 - i * 3.4;
    grooves.push(<circle key={"g" + i} cx="100" cy="100" r={r} fill="none" stroke="rgba(148,163,184,0.10)" strokeWidth="0.7" />);
  }
  const ridges = [];
  for (let i = 0; i < 60; i++) {
    const a = (i / 60) * Math.PI * 2;
    const r1 = 82, r2 = 93;
    ridges.push(<line key={"r" + i} x1={100 + Math.cos(a) * r1} y1={100 + Math.sin(a) * r1} x2={100 + Math.cos(a) * r2} y2={100 + Math.sin(a) * r2} stroke={i % 5 === 0 ? "rgba(251,191,36,0.55)" : "rgba(148,163,184,0.25)"} strokeWidth={i % 5 === 0 ? 2 : 1.1} strokeLinecap="round" />);
  }

  return (
    <div
      className="h-full w-full relative select-none"
      style={{ minWidth: JogWheel_MIN.base[0] + "rem", minHeight: JogWheel_MIN.base[1] + "rem" }}
    >
      <svg
        ref={svgRef}
        viewBox="0 0 200 200"
        preserveAspectRatio="xMidYMid meet"
        className={"absolute inset-0 h-full w-full touch-none cursor-grab transition-all duration-200 ease-out " + (drag ? "cursor-grabbing brightness-125" : hover ? "brightness-110" : "")}
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={up}
        onPointerCancel={up}
        onPointerEnter={() => setHover(true)}
        onPointerLeave={() => setHover(false)}
      >
        <defs>
          <radialGradient id={uid + "-body"} cx="35%" cy="25%" r="85%">
            <stop offset="0%" stopColor="#1e293b" />
            <stop offset="55%" stopColor="#0b1120" />
            <stop offset="100%" stopColor="#000000" />
          </radialGradient>
          <linearGradient id={uid + "-rim"} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={accent} stopOpacity="0.85" />
            <stop offset="50%" stopColor={accent} stopOpacity="0.22" />
            <stop offset="100%" stopColor={accent} stopOpacity="0.7" />
          </linearGradient>
          <radialGradient id={uid + "-label"} cx="40%" cy="30%" r="80%">
            <stop offset="0%" stopColor={isV ? "#155e75" : "#78350f"} />
            <stop offset="100%" stopColor="#020617" />
          </radialGradient>
          <radialGradient id={uid + "-glow"} cx="50%" cy="50%" r="50%">
            <stop offset="60%" stopColor={accent} stopOpacity="0" />
            <stop offset="100%" stopColor={accent} stopOpacity={spinning ? 0.35 : 0.12} />
          </radialGradient>
        </defs>

        <circle cx="100" cy="100" r="99" fill={"url(#" + uid + "-glow)"} className="transition-all duration-200" />
        <circle cx="100" cy="100" r="95" fill={"url(#" + uid + "-body")} stroke={"url(#" + uid + "-rim)"} strokeWidth="4" />
        <circle cx="100" cy="100" r="90" fill="none" stroke="rgba(0,0,0,0.8)" strokeWidth="3" />

        <g transform={rot} style={{ transition: drag ? "none" : "transform 90ms linear" }}>
          {isV ? grooves : ridges}
          {isV ? (
            <>
              <circle cx="100" cy="100" r="38" fill={"url(#" + uid + "-label")} stroke="rgba(34,211,238,0.45)" strokeWidth="1.5" />
              <circle cx="100" cy="100" r="30" fill="none" stroke="rgba(34,211,238,0.18)" strokeWidth="0.8" />
              <path d="M100 62 L100 12" stroke="#22d3ee" strokeWidth="3" strokeLinecap="round" opacity="0.9" />
              <circle cx="100" cy="24" r="6" fill="#22d3ee" opacity="0.95" />
            </>
          ) : (
            <>
              <circle cx="100" cy="100" r="60" fill="none" stroke="rgba(251,191,36,0.20)" strokeWidth="1" />
              <circle cx="100" cy="100" r="42" fill={"url(#" + uid + "-label")} stroke="rgba(251,191,36,0.45)" strokeWidth="1.5" />
              <rect x="97" y="12" width="6" height="34" rx="3" fill="#fbbf24" opacity="0.95" />
              <circle cx="100" cy="58" r="4" fill="#fbbf24" opacity="0.7" />
            </>
          )}
          <circle cx="100" cy="100" r="4" fill="#020617" stroke={accent} strokeWidth="1.2" />
        </g>

        <circle
          cx="100"
          cy="100"
          r="95"
          fill="none"
          stroke={accent}
          strokeWidth={drag ? 3 : 1.6}
          opacity={spinning ? 0.8 : 0.3}
          className={spinning ? "animate-pulse" : ""}
          style={{ transition: "all 200ms ease-out" }}
        />
        <ellipse cx="72" cy="58" rx="40" ry="22" fill="#ffffff" opacity="0.045" transform="rotate(-28 72 58)" />
      </svg>
    </div>
  );
}

type KnobProps = { value: number; min: number; max: number; onChange: (v: number) => void; mode?: 'continuous' | 'stepped'; steps?: number[]; detents?: number[] };

export const Knob_MIN = {"base":[2.5,2.5]};

export function Knob(props: KnobProps) {
  const { value, min, max, onChange, mode, steps, detents } = props;
  const uid = useRef("knob-" + Math.random().toString(36).slice(2)).current;
  const [drag, setDrag] = useState(false);
  const [hover, setHover] = useState(false);
  const ref = useRef<HTMLDivElement | null>(null);
  const startRef = useRef({ y: 0, v: 0 });

  const span = (max - min) || 1;
  const clamp = (v: number) => Math.max(min, Math.min(max, v));
  const list = (mode === 'stepped' && steps && steps.length) ? steps : null;
  const snap = (v: number) => {
    if (!list) return clamp(v);
    let best = list[0];
    for (const s of list) if (Math.abs(s - v) < Math.abs(best - v)) best = s;
    return best;
  };
  const norm = Math.max(0, Math.min(1, (clamp(value) - min) / span));
  const A0 = -135, A1 = 135;
  const ang = A0 + norm * (A1 - A0);

  const polar = (a: number, r: number) => {
    const rad = (a - 90) * Math.PI / 180;
    return [50 + r * Math.cos(rad), 50 + r * Math.sin(rad)];
  };
  const arcPath = (a0: number, a1: number, r: number) => {
    const [x0, y0] = polar(a0, r);
    const [x1, y1] = polar(a1, r);
    const large = Math.abs(a1 - a0) > 180 ? 1 : 0;
    const sweep = a1 > a0 ? 1 : 0;
    return "M " + x0 + " " + y0 + " A " + r + " " + r + " 0 " + large + " " + sweep + " " + x1 + " " + y1;
  };

  const apply = (v: number) => { const nv = snap(clamp(v)); if (nv !== value) onChange(nv); };

  const onDown = (e: any) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    startRef.current = { y: e.clientY, v: clamp(value) };
    setDrag(true);
  };
  const onMove = (e: any) => {
    if (!drag) return;
    const rect = ref.current?.getBoundingClientRect();
    const h = rect && rect.height ? rect.height : 100;
    const dy = (startRef.current.y - e.clientY) / h;
    apply(startRef.current.v + dy * span * 1.6);
  };
  const onUp = (e: any) => { if (drag) { e.currentTarget.releasePointerCapture?.(e.pointerId); setDrag(false); } };

  const marks: number[] = [];
  if (list) for (const s of list) marks.push(s);
  else if (detents) for (const d of detents) marks.push(d);

  const active = drag;

  return (
    <div
      ref={ref}
      className="h-full w-full relative touch-none cursor-ns-resize select-none"
      style={{ minWidth: Knob_MIN.base[0] + "rem", minHeight: Knob_MIN.base[1] + "rem" }}
      onPointerDown={onDown}
      onPointerMove={onMove}
      onPointerUp={onUp}
      onPointerCancel={onUp}
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => setHover(false)}
      onDoubleClick={() => apply(min + span / 2)}
    >
      <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full">
        <defs>
          <radialGradient id={uid + "-body"} cx="50%" cy="32%" r="72%">
            <stop offset="0%" stopColor="#3f3f46" />
            <stop offset="55%" stopColor="#1c1917" />
            <stop offset="100%" stopColor="#09090b" />
          </radialGradient>
          <linearGradient id={uid + "-arc"} x1="0" y1="1" x2="1" y2="0">
            <stop offset="0%" stopColor="#f59e0b" />
            <stop offset="100%" stopColor="#fcd34d" />
          </linearGradient>
          <filter id={uid + "-glow"} x="-60%" y="-60%" width="220%" height="220%">
            <feGaussianBlur stdDeviation={active ? 3.2 : 1.8} result="b" />
            <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
        </defs>

        {/* well */}
        <circle cx="50" cy="50" r="47" fill="#000" opacity="0.55" />
        {/* track */}
        <path d={arcPath(A0, A1, 41)} fill="none" stroke="#334155" strokeOpacity="0.7" strokeWidth="5" strokeLinecap="round" />
        {/* value arc */}
        <path
          d={arcPath(A0, ang, 41)}
          fill="none"
          stroke={"url(#" + uid + "-arc)"}
          strokeWidth="5"
          strokeLinecap="round"
          filter={"url(#" + uid + "-glow)"}
          style={{ transition: "d 120ms ease-out" }}
        />

        {/* detent / step marks */}
        {marks.map((m, i) => {
          const n = Math.max(0, Math.min(1, (m - min) / span));
          const a = A0 + n * (A1 - A0);
          const [x1, y1] = polar(a, 46.5);
          const [x2, y2] = polar(a, 35.5);
          const near = Math.abs(a - ang) < 2.5;
          return (
            <line
              key={"tk-" + i}
              x1={x1} y1={y1} x2={x2} y2={y2}
              stroke={near ? "#fcd34d" : "#64748b"}
              strokeOpacity={near ? 1 : 0.55}
              strokeWidth={near ? 2.4 : 1.4}
              strokeLinecap="round"
              style={{ transition: "all 150ms ease-out" }}
            />
          );
        })}

        {/* body */}
        <circle cx="50" cy="50" r="31" fill={"url(#" + uid + "-body")"} stroke="#f59e0b" strokeOpacity={active ? 0.75 : hover ? 0.55 : 0.4} strokeWidth="1.6" style={{ transition: "all 200ms ease-out" }} />
        <circle cx="50" cy="50" r="31" fill="none" stroke="#000" strokeOpacity="0.6" strokeWidth="3" transform="translate(0,1.4)" opacity="0.35" />

        {/* knurls */}
        <g opacity={hover || active ? 0.5 : 0.28} style={{ transition: "opacity 200ms ease-out" }}>
          {Array.from({ length: 24 }).map((_, i) => {
            const a = (i * 360) / 24;
            const [x1, y1] = polar(a, 30.5);
            const [x2, y2] = polar(a, 26.5);
            return <line key={"kn-" + i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#a8a29e" strokeWidth="1" strokeLinecap="round" />;
          })}
        </g>

        {/* rotating pointer */}
        <g style={{ transform: "rotate(" + ang + "deg)", transformOrigin: "50px 50px", transition: drag ? "none" : "transform 120ms ease-out" }}>
          <line x1="50" y1="26" x2="50" y2="12" stroke="#fde68a" strokeWidth="3.4" strokeLinecap="round" filter={"url(#" + uid + "-glow)"} />
          <circle cx="50" cy="22.5" r="2.2" fill="#fef3c7" />
        </g>

        {/* center cap */}
        <circle cx="50" cy="50" r="7" fill="#18181b" stroke="#f59e0b" strokeOpacity={active ? 0.8 : 0.35} strokeWidth="1.2" style={{ transition: "all 200ms ease-out" }} />
        <circle cx="50" cy="50" r="2.6" fill="#fbbf24" opacity={active ? 1 : 0.55} style={{ transition: "opacity 200ms ease-out" }}>
          {active ? <animate attributeName="r" values="2.2;3.4;2.2" dur="1.1s" repeatCount="indefinite" /> : null}
        </circle>
      </svg>
    </div>
  );
}

type TuningNeedleProps = { value: number; min: number; max: number };

export const TuningNeedle_MIN = {"base":[3,1.5]};

export function TuningNeedle(props: TuningNeedleProps) {
  const uid = useRef("tuningneedle-" + Math.random().toString(36).slice(2)).current;
  const { value, min, max } = props;
  const span = max - min;
  const raw = span === 0 ? 0 : (value - min) / span;
  const t = Math.max(0, Math.min(1, isFinite(raw) ? raw : 0));
  const pct = t * 100;

  const prev = useRef(t);
  const [moving, setMoving] = useState(false);
  useEffect(() => {
    if (Math.abs(prev.current - t) > 0.0005) {
      prev.current = t;
      setMoving(true);
      const id = setTimeout(() => setMoving(false), 420);
      return () => clearTimeout(id);
    }
  }, [t]);

  const floor = TuningNeedle_MIN.base;

  return (
    <div
      className="relative h-full w-full overflow-hidden"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
    >
      {/* travel groove */}
      <div className="absolute inset-x-0 top-1/2 h-[2px] -translate-y-1/2 bg-[#0d0818] shadow-[inset_0_1px_3px_rgba(0,0,0,0.7)]" />
      {/* filled travel */}
      <div
        className="absolute top-1/2 left-0 h-[2px] -translate-y-1/2 bg-gradient-to-r from-fuchsia-500/30 to-cyan-400/60 transition-all duration-300 ease-out"
        style={{ width: pct + "%" }}
      />

      {/* halo */}
      <div
        className={
          "pointer-events-none absolute top-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-300 ease-out " +
          (moving ? "opacity-90" : "opacity-50")
        }
        style={{
          left: pct + "%",
          width: "2.2rem",
          height: "2.2rem",
          background:
            "radial-gradient(circle, rgba(34,211,238,0.45) 0%, rgba(217,70,239,0.18) 45%, rgba(0,0,0,0) 70%)",
        }}
      />

      {/* needle */}
      <div
        className="absolute inset-y-0 -translate-x-1/2 transition-all duration-300 ease-out"
        style={{ left: pct + "%", width: "1.1rem" }}
      >
        <svg
          viewBox="0 0 22 100"
          preserveAspectRatio="none"
          className="absolute inset-0 h-full w-full"
        >
          <defs>
            <linearGradient id={uid + "-line"} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#f0abfc" stopOpacity="0.15" />
              <stop offset="18%" stopColor="#e879f9" stopOpacity="0.95" />
              <stop offset="50%" stopColor="#67e8f9" stopOpacity="1" />
              <stop offset="82%" stopColor="#e879f9" stopOpacity="0.95" />
              <stop offset="100%" stopColor="#f0abfc" stopOpacity="0.15" />
            </linearGradient>
            <linearGradient id={uid + "-soft"} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#22d3ee" stopOpacity="0" />
              <stop offset="50%" stopColor="#22d3ee" stopOpacity="0.55" />
              <stop offset="100%" stopColor="#22d3ee" stopOpacity="0" />
            </linearGradient>
          </defs>
          <rect x="8" y="0" width="6" height="100" fill={"url(#" + uid + "-soft)"} />
          <rect x="10.2" y="0" width="1.6" height="100" fill={"url(#" + uid + "-line")} />
        </svg>

        {/* caps + core, aspect-preserved */}
        <svg
          viewBox="0 0 22 22"
          preserveAspectRatio="xMidYMid meet"
          className="absolute left-0 top-0 w-full"
          style={{ height: "40%" }}
        >
          <polygon
            points="11,2 17,10 11,8 5,10"
            fill="#22d3ee"
            className={moving ? "animate-pulse" : ""}
          />
        </svg>
        <svg
          viewBox="0 0 22 22"
          preserveAspectRatio="xMidYMid meet"
          className="absolute bottom-0 left-0 w-full"
          style={{ height: "40%" }}
        >
          <polygon
            points="11,20 17,12 11,14 5,12"
            fill="#e879f9"
            className={moving ? "animate-pulse" : ""}
          />
        </svg>

        {/* core gem */}
        <div className="absolute inset-0 flex items-center justify-center">
          <svg viewBox="0 0 20 20" preserveAspectRatio="xMidYMid meet" className="h-[55%] w-full">
            <defs>
              <radialGradient id={uid + "-core"}>
                <stop offset="0%" stopColor="#ffffff" stopOpacity="0.95" />
                <stop offset="40%" stopColor="#67e8f9" stopOpacity="0.9" />
                <stop offset="100%" stopColor="#a21caf" stopOpacity="0.15" />
              </radialGradient>
            </defs>
            <circle
              cx="10"
              cy="10"
              r={moving ? 6.4 : 4.6}
              fill={"url(#" + uid + "-core)"}
              className="transition-all duration-300 ease-out"
            />
            <circle
              cx="10"
              cy="10"
              r="7.4"
              fill="none"
              stroke="#22d3ee"
              strokeOpacity={moving ? 0.8 : 0.35}
              strokeWidth="0.7"
              className="transition-all duration-300 ease-out"
            />
          </svg>
        </div>
      </div>
    </div>
  );
}

type PerkNodeProps = { state: 'locked' | 'available' | 'unlocked'; rank: number; maxRank: number; onSpend: (id: string) => void; id: string; hover?: (id: string | null) => void; children?: React.ReactNode };

export const PerkNode_MIN = {"base":[3.5,3.5]};

const PerkNodeHexPath = (r: number) => {
  let d = "";
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 180) * (60 * i - 90);
    const x = 50 + r * Math.cos(a);
    const y = 50 + r * Math.sin(a);
    d += (i === 0 ? "M" : "L") + x.toFixed(2) + " " + y.toFixed(2) + " ";
  }
  return d + "Z";
};

const PerkNodeArc = (r: number, a0: number, a1: number) => {
  const p = (a: number) => {
    const rad = (Math.PI / 180) * (a - 90);
    return [50 + r * Math.cos(rad), 50 + r * Math.sin(rad)];
  };
  const [x0, y0] = p(a0);
  const [x1, y1] = p(a1);
  const large = a1 - a0 > 180 ? 1 : 0;
  return "M" + x0.toFixed(2) + " " + y0.toFixed(2) + " A" + r + " " + r + " 0 " + large + " 1 " + x1.toFixed(2) + " " + y1.toFixed(2);
};

export function PerkNode(props: PerkNodeProps) {
  const { state, rank, maxRank, onSpend, id, hover, children } = props;
  const uid = useRef("perknode-" + Math.random().toString(36).slice(2)).current;
  const [hot, setHot] = useState(false);
  const [press, setPress] = useState(false);
  const [pulse, setPulse] = useState(0);
  const prevRank = useRef(rank);

  useEffect(() => {
    if (rank !== prevRank.current) {
      prevRank.current = rank;
      setPulse((p) => p + 1);
    }
  }, [rank]);

  const floor = PerkNode_MIN.base;
  const locked = state === "locked";
  const maxed = rank >= maxRank && maxRank > 0;
  const interactive = !locked && !maxed;

  const accent = locked ? "#737373" : state === "unlocked" ? "#e879f9" : "#22d3ee";
  const accentDim = locked ? "rgba(115,115,115,0.25)" : state === "unlocked" ? "rgba(232,121,249,0.28)" : "rgba(34,211,238,0.25)";
  const glow = hot && interactive ? 1 : 0;

  const segs = Math.max(0, Math.min(maxRank, 12));
  const gapDeg = segs > 1 ? Math.min(10, 120 / segs) : 0;
  const span = segs > 0 ? 360 / segs : 360;

  const textColor = locked ? "text-neutral-500" : state === "unlocked" ? "text-fuchsia-300" : "text-cyan-200";

  return (
    <div
      className="relative h-full w-full"
      style={{ minWidth: floor[0] + "rem", minHeight: floor[1] + "rem" }}
      onPointerEnter={() => { setHot(true); if (hover) hover(id); }}
      onPointerLeave={() => { setHot(false); setPress(false); if (hover) hover(null); }}
      onPointerDown={(e) => { if (!interactive) return; (e.currentTarget as any).setPointerCapture?.(e.pointerId); setPress(true); }}
      onPointerUp={() => { if (press && interactive) onSpend(id); setPress(false); }}
      onPointerCancel={() => setPress(false)}
    >
      <div
        className={"absolute inset-0 transition-all duration-200 ease-out touch-none " + (locked ? "opacity-40 grayscale" : "") + (interactive ? " cursor-pointer" : "")}
        style={{ transform: press ? "scale(0.95)" : hot && interactive ? "scale(1.04)" : "scale(1)" }}
      >
        <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full">
          <defs>
            <radialGradient id={uid + "-core"} cx="50%" cy="38%" r="70%">
              <stop offset="0%" stopColor={accent} stopOpacity={state === "unlocked" ? 0.45 : locked ? 0.06 : 0.18 + glow * 0.18} />
              <stop offset="60%" stopColor="#000000" stopOpacity="0.85" />
              <stop offset="100%" stopColor="#000000" stopOpacity="0.95" />
            </radialGradient>
            <linearGradient id={uid + "-edge"} x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor={accent} stopOpacity={locked ? 0.4 : 1} />
              <stop offset="100%" stopColor={accent} stopOpacity={locked ? 0.15 : 0.45} />
            </linearGradient>
            <filter id={uid + "-blur"} x="-60%" y="-60%" width="220%" height="220%">
              <feGaussianBlur stdDeviation={2.5 + glow * 2} />
            </filter>
          </defs>

          {/* outer glow halo */}
          {!locked && (
            <path
              d={PerkNodeHexPath(42)}
              fill="none"
              stroke={accent}
              strokeWidth={state === "unlocked" ? 4 : 2.5}
              opacity={state === "unlocked" ? 0.55 : 0.25 + glow * 0.4}
              filter={"url(#" + uid + "-blur)"}
              className="transition-all duration-200 ease-out"
            />
          )}

          {/* body */}
          <path d={PerkNodeHexPath(42)} fill={"url(#" + uid + "-core")" } />
          <path
            d={PerkNodeHexPath(42)}
            fill="none"
            stroke={"url(#" + uid + "-edge)"}
            strokeWidth={state === "unlocked" ? 3 : 2}
            strokeLinejoin="miter"
            className="transition-all duration-200 ease-out"
          />

          {/* inner etch */}
          <path d={PerkNodeHexPath(33)} fill="none" stroke={accent} strokeOpacity={0.18} strokeWidth="0.7" strokeDasharray="4 3" />

          {/* rank segments */}
          {segs > 0 && Array.from({ length: segs }).map((_, i) => {
            const a0 = i * span + gapDeg / 2;
            const a1 = (i + 1) * span - gapDeg / 2;
            const filled = i < rank;
            return (
              <path
                key={"seg-" + i}
                d={PerkNodeArc(47, a0, a1)}
                fill="none"
                stroke={filled ? accent : accentDim}
                strokeWidth={filled ? 4 : 2.2}
                strokeLinecap="butt"
                opacity={filled ? 1 : 0.6}
                className="transition-all duration-300 ease-out"
              />
            );
          })}

          {/* corner cursors when available */}
          {state === "available" && !locked && (
            <g opacity={0.5 + glow * 0.5} className="transition-all duration-200 ease-out">
              <path d="M50 4 L46 10 L54 10 Z" fill={accent} />
              <path d="M50 96 L46 90 L54 90 Z" fill={accent} />
            </g>
          )}

          {/* locked latch */}
          {locked && (
            <g stroke="#a3a3a3" strokeWidth="2.2" fill="none" opacity="0.8">
              <rect x="42" y="70" width="16" height="12" rx="1.5" fill="#0a0a0a" />
              <path d="M45.5 70 v-4 a4.5 4.5 0 0 1 9 0 v4" />
            </g>
          )}

          {/* maxed spark */}
          {maxed && !locked && (
            <circle cx="50" cy="50" r="46" fill="none" stroke={accent} strokeOpacity="0.25" strokeWidth="0.8" className="animate-pulse" />
          )}

          {/* value-change ping */}
          {pulse > 0 && (
            <circle key={"ping-" + pulse} cx="50" cy="50" r="30" fill="none" stroke={accent} strokeWidth="3" className="animate-ping" opacity="0.6" />
          )}
        </svg>

        {children != null && children !== false && (
          <div className="absolute inset-[26%] flex items-center justify-center">
            <FitText className={"font-mono font-bold tracking-widest uppercase transition-colors duration-200 " + textColor}>{children}</FitText>
          </div>
        )}
      </div>
    </div>
  );
}

type ZoomPanControlsProps = {
  zoom: number;
  min: number;
  max: number;
  onZoomChange: (zoom: number) => void;
  onPan?: (delta: { x: number; y: number }) => void;
  onRecenter?: () => void;
};

export const ZoomPanControls_MIN = {"base":[5,5]};

export function ZoomPanControls(props: ZoomPanControlsProps) {
  const { zoom, min, max, onZoomChange, onPan, onRecenter } = props;
  const uid = useRef("zpc-" + Math.random().toString(36).slice(2)).current;
  const [press, setPress] = useState<string | null>(null);
  const [hover, setHover] = useState<string | null>(null);
  const [flash, setFlash] = useState(0);

  const repeatFn = useRef<(() => void) | null>(null);
  const timers = useRef<{ t: any; i: any }>({ t: null, i: null });

  useEffect(() => {
    return () => {
      if (timers.current.t) clearTimeout(timers.current.t);
      if (timers.current.i) clearInterval(timers.current.i);
    };
  }, []);

  const lo = Math.min(min, max);
  const hi = Math.max(min, max);
  const clamp = (v: number) => Math.min(hi, Math.max(lo, v));
  const z = clamp(zoom);
  const t = hi > lo ? (z - lo) / (hi - lo) : 0;

  const P = (aDeg: number, r: number) => {
    const a = (aDeg * Math.PI) / 180;
    return [50 + r * Math.cos(a), 50 + r * Math.sin(a)];
  };
  const sector = (a0: number, a1: number, r0: number, r1: number) => {
    const p0 = P(a0, r0), p1 = P(a0, r1), p2 = P(a1, r1), p3 = P(a1, r0);
    const large = Math.abs(a1 - a0) > 180 ? 1 : 0;
    return (
      "M " + p0[0] + " " + p0[1] +
      " L " + p1[0] + " " + p1[1] +
      " A " + r1 + " " + r1 + " 0 " + large + " 1 " + p2[0] + " " + p2[1] +
      " L " + p3[0] + " " + p3[1] +
      " A " + r0 + " " + r0 + " 0 " + large + " 0 " + p0[0] + " " + p0[1] + " Z"
    );
  };
  const arc = (a0: number, a1: number, r: number) => {
    const p0 = P(a0, r), p1 = P(a1, r);
    const large = Math.abs(a1 - a0) > 180 ? 1 : 0;
    return "M " + p0[0] + " " + p0[1] + " A " + r + " " + r + " 0 " + large + " 1 " + p1[0] + " " + p1[1];
  };

  const stop = () => {
    if (timers.current.t) clearTimeout(timers.current.t);
    if (timers.current.i) clearInterval(timers.current.i);
    timers.current = { t: null, i: null };
    repeatFn.current = null;
    setPress(null);
  };

  const begin = (e: any, key: string, fn: () => void, repeat: boolean) => {
    e.preventDefault();
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) {}
    setPress(key);
    setFlash((f) => f + 1);
    fn();
    if (repeat) {
      repeatFn.current = fn;
      timers.current.t = setTimeout(() => {
        timers.current.i = setInterval(() => {
          if (repeatFn.current) repeatFn.current();
        }, 110);
      }, 340);
    }
  };

  const step = 0.16 / Math.max(0.25, z);
  const pan = (dx: number, dy: number) => () => { if (onPan) onPan({ x: dx * step, y: dy * step }); };
  const zIn = () => { const n = clamp(z * 1.25); if (n !== z) onZoomChange(n); };
  const zOut = () => { const n = clamp(z / 1.25); if (n !== z) onZoomChange(n); };

  const canIn = z < hi - 1e-6;
  const canOut = z > lo + 1e-6;

  const R0 = 21, R1 = 39;
  const GAP = 4;
  const cards: { k: string; c: number; dx: number; dy: number }[] = [
    { k: "up", c: -90, dx: 0, dy: -1 },
    { k: "right", c: 0, dx: 1, dy: 0 },
    { k: "down", c: 90, dx: 0, dy: 1 },
    { k: "left", c: 180, dx: -1, dy: 0 },
  ];

  const stateFill = (k: string, base: string, act: string) =>
    press === k ? act : hover === k ? base : "transparent";

  const gaugeStart = 128, gaugeSpan = 284;
  const gaugeEnd = gaugeStart + gaugeSpan * t;

  const btnProps = (k: string, fn: () => void, repeat: boolean, enabled: boolean) =>
    enabled
      ? {
          onPointerDown: (e: any) => begin(e, k, fn, repeat),
          onPointerUp: stop,
          onPointerCancel: stop,
          onPointerEnter: () => setHover(k),
          onPointerLeave: () => { setHover(null); },
          style: { cursor: "pointer" as const },
        }
      : {};

  return (
    <div
      className="relative h-full w-full touch-none select-none"
      style={{ minWidth: ZoomPanControls_MIN.base[0] + "rem", minHeight: ZoomPanControls_MIN.base[1] + "rem" }}
    >
      <svg viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full overflow-visible">
        <defs>
          <radialGradient id={uid + "-core"} cx="50%" cy="35%" r="70%">
            <stop offset="0%" stopColor="#1a2a3a" />
            <stop offset="100%" stopColor="#07070c" />
          </radialGradient>
          <linearGradient id={uid + "-gauge"} x1="0" y1="1" x2="1" y2="0">
            <stop offset="0%" stopColor="#22d3ee" />
            <stop offset="60%" stopColor="#fde047" />
            <stop offset="100%" stopColor="#d946ef" />
          </linearGradient>
          <filter id={uid + "-glow"} x="-60%" y="-60%" width="220%" height="220%">
            <feGaussianBlur stdDeviation="1.8" result="b" />
            <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
        </defs>

        {/* recessed body */}
        <circle cx="50" cy="50" r="46" fill="#07070c" stroke="rgba(34,211,238,0.22)" strokeWidth="0.8" />
        <circle cx="50" cy="50" r="41.5" fill="url(#" + "" + uid + "-core)" style={{ fill: "url(#" + uid + "-core)" }} />

        {/* slow rotating decorative ring */}
        <g className="animate-[spin_16s_linear_infinite]" style={{ transformOrigin: "50px 50px" }}>
          <circle cx="50" cy="50" r="44" fill="none" stroke="rgba(217,70,239,0.35)" strokeWidth="0.5" strokeDasharray="3 7" />
        </g>

        {/* zoom gauge */}
        <path d={arc(gaugeStart, gaugeStart + gaugeSpan, 45)} fill="none" stroke="rgba(8,51,68,0.9)" strokeWidth="3.2" strokeLinecap="round" />
        <path
          d={arc(gaugeStart, Math.max(gaugeStart + 0.4, gaugeEnd), 45)}
          fill="none"
          stroke={"url(#" + uid + "-gauge)"}
          strokeWidth="3.2"
          strokeLinecap="round"
          filter={"url(#" + uid + "-glow)"}
          className="transition-all duration-500 ease-[cubic-bezier(0.22,1,0.36,1)]"
        />
        {[0, 0.25, 0.5, 0.75, 1].map((f, i) => {
          const a = gaugeStart + gaugeSpan * f;
          const p1 = P(a, 41.6), p2 = P(a, 48.4);
          return (
            <line key={"tk-" + i} x1={p1[0]} y1={p1[1]} x2={p2[0]} y2={p2[1]}
              stroke={f <= t ? "rgba(253,224,71,0.85)" : "rgba(34,211,238,0.3)"} strokeWidth="0.7"
              className="transition-all duration-500" />
          );
        })}
        {/* gauge head */}
        <circle
          cx={P(gaugeEnd, 45)[0]} cy={P(gaugeEnd, 45)[1]} r="2.1"
          fill="#fde047" filter={"url(#" + uid + "-glow)"}
          className="transition-all duration-500 ease-[cubic-bezier(0.22,1,0.36,1)]"
        />

        {/* pan wedges */}
        {cards.map((c) => {
          const active = !!onPan;
          const k = "pan-" + c.k;
          const isP = press === k;
          const isH = hover === k && active;
          return (
            <g key={k} {...btnProps(k, pan(c.dx, c.dy), true, active)} opacity={active ? 1 : 0.28}>
              <path
                d={sector(c.c - 22.5 + GAP / 2, c.c + 22.5 - GAP / 2, R0, R1)}
                fill={isP ? "rgba(253,224,71,0.35)" : isH ? "rgba(34,211,238,0.16)" : "rgba(34,211,238,0.05)"}
                stroke={isP ? "#fde047" : isH ? "rgba(34,211,238,0.8)" : "rgba(34,211,238,0.28)"}
                strokeWidth="0.7"
                className="transition-all duration-200 ease-out"
                filter={isP ? "url(#" + uid + "-glow)" : undefined}
              />
              <g
                className="transition-transform duration-200 ease-out"
                style={{
                  transformOrigin: "50px 50px",
                  transform: isP ? "translate(" + c.dx * 1.8 + "px," + c.dy * 1.8 + "px)" : "none",
                }}
              >
                <path
                  d={
                    "M " + P(c.c, R1 - 5)[0] + " " + P(c.c, R1 - 5)[1] +
                    " L " + P(c.c - 8, R1 - 11.5)[0] + " " + P(c.c - 8, R1 - 11.5)[1] +
                    " L " + P(c.c + 8, R1 - 11.5)[0] + " " + P(c.c + 8, R1 - 11.5)[1] + " Z"
                  }
