                fill={isP ? "rgba(253,224,71,0.4)" : isH ? "rgba(253,224,71,0.16)" : "rgba(253,224,71,0.06)"}
                stroke={isP || isH ? "rgba(253,224,71,0.9)" : "rgba(253,224,71,0.35)"}
                strokeWidth="0.7"
                className="transition-all duration-200 ease-out"
                filter={isP ? "url(#" + uid + "-glow)" : undefined}
              />
              <g
                className="transition-transform duration-200 ease-out"
                style={{ transformOrigin: cx + "px " + cy + "px", transform: isP ? "scale(1.22)" : isH ? "scale(1.1)" : "scale(1)" }}
              >
                <line x1={cx - 4} y1={cy} x2={cx + 4} y2={cy}
                  stroke={isP || isH ? "#fde047" : "rgba(253,224,71,0.75)"} strokeWidth="1.5" strokeLinecap="round" />
                {b.k === "zin" && (
                  <line x1={cx} y1={cy - 4} x2={cx} y2={cy + 4}
                    stroke={isP || isH ? "#fde047" : "rgba(253,224,71,0.75)"} strokeWidth="1.5" strokeLinecap="round" />
                )}
              </g>
            </g>
          );
        })}

        {/* idle diagonal notches */}
        {[45, -135].map((a, i) => (
          <path key={"nd-" + i} d={sector(a - 22.5 + GAP / 2, a + 22.5 - GAP / 2, R0, R1)}
            fill="rgba(34,211,238,0.035)" stroke="rgba(34,211,238,0.14)" strokeWidth="0.5" />
        ))}

        {/* center hub */}
        <g
          {...btnProps("center", () => { if (onRecenter) onRecenter(); }, false, !!onRecenter)}
        >
          <circle cx="50" cy="50" r="18"
            fill={press === "center" ? "rgba(253,224,71,0.25)" : "#07070c"}
            stroke={press === "center" ? "#fde047" : hover === "center" && onRecenter ? "rgba(34,211,238,0.85)" : "rgba(34,211,238,0.35)"}
            strokeWidth="0.8"
            className="transition-all duration-200 ease-out"
            filter={press === "center" ? "url(#" + uid + "-glow)" : undefined}
          />
          <g
            className="transition-transform duration-300 ease-out"
            style={{ transformOrigin: "50px 50px", transform: press === "center" ? "rotate(90deg) scale(1.12)" : hover === "center" && onRecenter ? "scale(1.06)" : "none" }}
            opacity={onRecenter ? 1 : 0.45}
          >
            <circle cx="50" cy="50" r="9.5" fill="none" stroke="rgba(217,70,239,0.5)" strokeWidth="0.6" strokeDasharray="2.4 3" />
            <circle cx="50" cy="50" r="4.6" fill="none"
              stroke={press === "center" ? "#fde047" : "rgba(103,232,249,0.9)"} strokeWidth="1.2" />
            <circle cx="50" cy="50" r="1.5" fill={press === "center" ? "#fde047" : "#22d3ee"} />
            {[0, 90, 180, 270].map((a) => {
              const p1 = P(a, 6.6), p2 = P(a, 11.5);
              return (
                <line key={"cr-" + a} x1={p1[0]} y1={p1[1]} x2={p2[0]} y2={p2[1]}
                  stroke={press === "center" ? "#fde047" : "rgba(103,232,249,0.8)"} strokeWidth="1.1" strokeLinecap="round" />
              );
            })}
          </g>
        </g>

        {/* press flash ring */}
        {press && (
          <circle key={"fl-" + flash} cx="50" cy="50" r="46" fill="none"
            stroke="rgba(217,70,239,0.55)" strokeWidth="1" className="animate-ping" />
        )}
      </svg>
    </div>
  );
}

