            <div className="w-[2.4rem] h-[1.9rem]">
              <ActionButton onPress={recenter} tone="accent">
                <span className="font-black text-[0.8em] tracking-[0.1em]">CTR</span>
              </ActionButton>
            </div>
            <div className="w-[2.4rem] h-[1.9rem]">
              <ActionButton onPress={() => setView((v) => ({ ...v, x: Math.min(1, +(v.x + 0.08).toFixed(3)) }))}>
                <span className="font-black">▶</span>
              </ActionButton>
            </div>
          </div>
          <div className="w-[2.4rem] h-[1.9rem]">
            <ActionButton onPress={() => setView((v) => ({ ...v, y: Math.min(1, +(v.y + 0.08).toFixed(3)) }))}>
              <span className="font-black">▼</span>
            </ActionButton>
          </div>
          <div className="mt-1 flex flex-col gap-2">
            <div className="w-[2.4rem] h-[1.9rem]">
              <ActionButton onPress={() => zoomBy(0.25)} tone="accent" disabled={view.zoom >= 3}>
                <span className="font-black">＋</span>
              </ActionButton>
            </div>
            <div className="w-[2.4rem] h-[1.9rem]">
              <ActionButton onPress={() => zoomBy(-0.25)} tone="accent" disabled={view.zoom <= 0.6}>
                <span className="font-black">－</span>
              </ActionButton>
            </div>
          </div>
        </div>

        {/* SELECTION HUD */}
        {sel && (
          <div className="absolute left-3 bottom-3 max-w-[22rem] bg-[#12091c]/95 backdrop-blur-sm border border-[#00f0ff]/35 ring-1 ring-[#ff005c]/10 rounded-md shadow-[0_0_20px_rgba(0,240,255,0.15)] p-3 transition-all duration-200 ease-out">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-medium tracking-[0.1em] uppercase text-[#bd00ff] border border-[#bd00ff]/40 rounded-[3px] px-2 py-[2px]">
                {kindLabel[sel.kind]}
              </span>
              <span className="text-[10px] font-medium tracking-[0.1em] uppercase text-[#4a5568]">
                {sel.x.toFixed(2)} / {sel.y.toFixed(2)}
              </span>
            </div>
            <div className="mt-2 text-sm font-black tracking-[0.05em] uppercase text-[#fcee0a] drop-shadow-[0_0_6px_rgba(252,238,10,0.5)] truncate">
              {sel.label}
            </div>
            <div className="text-xs font-semibold tracking-[0.15em] uppercase text-[#7de3ef] truncate">
              {sel.district}
            </div>
            <div className="mt-2 h-[3px] w-full bg-[#080410]/90 border border-[#00f0ff]/20 rounded-[2px] overflow-clip">
              <div
                className="h-full bg-[#fcee0a] transition-all duration-500 ease-out shadow-[0_0_10px_rgba(252,238,10,0.4)]"
                style={{ width: 25 + (pingT % 76) + "%" }}
              />
            </div>
          </div>
        )}
      </div>

      {/* FOOTER */}
      <div className="h-7 flex-none px-3 bg-[#080410]/95 border-t border-[#ff005c]/25 flex items-center gap-4 overflow-clip">
        {(["fastTravel", "mainQuest", "sideQuest", "gig", "vendor"] as Kind[]).map((k) => (
          <span
            key={k}
            className="text-[10px] font-medium tracking-[0.1em] uppercase text-[#4a5568] flex items-center gap-1"
          >
            <span className="text-[#00f0ff]">{kindGlyph[k]}</span>
            {kindLabel[k]}
          </span>
        ))}
        <div className="flex-1 min-w-0" />
        <span className="text-[10px] font-medium tracking-[0.1em] uppercase text-[#ff005c] animate-pulse">
          ROUTE ACTIVE
        </span>
      </div>
    </div>
  );
}
